'use client';

import React, { useState } from 'react';

export default function Portfolio() {
  const categories = ['همه', 'طراحی سایت', 'پلتفرم اختصاصی', 'داشبورد مدیریتی'];
  const [activeCategory, setActiveCategory] = useState('همه');

  const projects = [
    {
      id: 1,
      title: "داشبورد منابع انسانی",
      category: "داشبورد مدیریتی",
      image: "/portfolio/project-1.jpg",
    },
    {
      id: 2,
      title: "سیستم تسک روابط عمومی",
      category: "پلتفرم اختصاصی",
      image: "/portfolio/project-2.jpg", 
    },
    {
      id: 3,
      title: "فروشگاه ارگانیک",
      category: "طراحی سایت",
      image: "/portfolio/project-3.jpg",
    },
    {
      id: 4,
      title: "سیستم مدیریت ناوگان",
      category: "پلتفرم اختصاصی",
      image: "/portfolio/project-4.jpg",
    },
    {
      id: 5,
      title: "لندینگ‌پیج زیبایی",
      category: "طراحی سایت",
      image: "/portfolio/project-5.jpg",
    },
    {
      id: 6,
      title: "پرتال سازمانی B2B",
      category: "داشبورد مدیریتی",
      image: "/portfolio/project-6.jpg",
    }
  ];

  const filteredProjects = activeCategory === 'همه' 
    ? projects 
    : projects.filter(project => project.category === activeCategory);

  return (
    <section id="portfolio" className="w-full py-16 bg-white border-t border-slate-100">
      <div className="max-w-7xl mx-auto px-6">
        
        {/* هدر بسیار ساده */}
        <div className="flex flex-col md:flex-row justify-between items-end mb-10 gap-6">
          <div>
            <h2 className="text-2xl md:text-3xl font-black text-slate-800 mb-2">
              خروجی‌های <span className="text-blue-600">دژاوب</span>
            </h2>
            <p className="text-slate-500 text-sm font-light">
              آرشیو پروژه‌ها و پلتفرم‌های توسعه‌یافته
            </p>
          </div>
          
          {/* فیلترهای ظریف */}
          <div className="flex flex-wrap gap-2">
            {categories.map((category) => (
              <button
                key={category}
                onClick={() => setActiveCategory(category)}
                className={`px-3 py-1.5 rounded-full text-xs font-bold transition-colors ${
                  activeCategory === category 
                    ? 'bg-slate-800 text-white' 
                    : 'bg-slate-50 text-slate-500 hover:bg-slate-100 hover:text-slate-800'
                }`}
              >
                {category}
              </button>
            ))}
          </div>
        </div>

        {/* گرید ۳ ستونه و مینیمال */}
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6 md:gap-8">
          {filteredProjects.map((project) => (
            <div key={project.id} className="group cursor-pointer flex flex-col gap-3">
              
              {/* کادر تصویر فشرده */}
              <div className="relative w-full aspect-[4/3] rounded-xl overflow-hidden bg-slate-100 border border-slate-100">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img 
                  src={project.image} 
                  alt={project.title}
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                  onError={(e) => {
                    (e.target as HTMLImageElement).style.display = 'none';
                  }}
                />
              </div>

              {/* متن‌های زیر عکس - بدون هیچ باکس اضافه‌ای */}
              <div>
                <h3 className="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors">
                  {project.title}
                </h3>
                <p className="text-xs text-slate-400 mt-0.5">
                  {project.category}
                </p>
              </div>
              
            </div>
          ))}
        </div>

      </div>
    </section>
  );
}